":"zh-a1-u12-l05-e03","options_hash":"v1:12fc850d8b794e99131a0f1b322f5fb5fcd50a70fcb51be706463d79362784bd"},{"exercise_id":"zh-a1-u12-l05-e04","item_id":"zh-a1-u12-l05-e04","options_hash":"v1:eb2038bfbe41a0a615750ba0fc165246eaf7833e9ad5d63324337ba640df2685"},{"exercise_id":"zh-a1-u12-l05-e05","item_id":"zh-a1-u12-l05-e05","options_hash":"v1:b0be6384413bfcaa3559112be459fea3b27d9237fa0674ba1557ce77ba707221"},{"exercise_id":"zh-a1-u12-listen-e01","item_id":"zh-a1-u12-l05-e02","options_hash":"v1:9e3b6e65bbfefc11eaf38a7708ed4413abc25ef5c03405c2a34ecd55d736f068"},{"exercise_id":"zh-a1-u12-listen-e02","item_id":"zh.gen.listen_choice.zh-mai-vender","options_hash":"v1:7c8272b9c8839b3f5662c2cd344a3433d4009fd198b87330ddc315965f7ef1ea"},{"exercise_id":"zh-a1-u12-listen-e03","item_id":"zh-a1-u12-l01-e06","options_hash":"v1:70e5a7e7f596d435582e850d2fbae97769125547af62ba43f805609f60c60e9a"},{"exercise_id":"zh-a1-u12-listen-e04","item_id":"zh.gen.listen_choice.zh-kuai","options_hash":"v1:0643cb448b734443d4c8481d1a3c56c7d97d07d5ccf923ff706761797ad214a1"},{"exercise_id":"zh-a1-u12-listen-e05","item_id":"zh-a1-u12-l03-e04","options_hash":"v1:01f93a79d61e8f5bb63ea7c078ac0c949e70cfc3e994e2830d34f7bc109d28cf"},{"exercise_id":"zh-a1-u12-listen-e06","item_id":"zh.gen.listen_choice.zh-duoshao-qian","options_hash":"v1:16832cd6c2395b873f190ed6f8ebab7650366506b5ce7bca6c5e9046440e816f"},{"exercise_id":"zh-a1-u12-listen-e07","item_id":"zh.gen.listen_choice.zh-zenmeyang","options_hash":"v1:39679c0827130d2631c27e4407621c929c9a435f5142c3fec387a3dfc31e5f59"},{"exercise_id":"zh-a1-u12-listen-e08","item_id":"zh.gen.listen_choice.zh-gui","options_hash":"v1:8fdcfbc291292a35c6af428c6907cf9c2bf5d58fa3b7bc15efe961090a46aeec"},{"exercise_id":"zh-a1-u12-listen-e09","item_id":"zh.gen.listen_choice.zh-yigong","options_hash":"v1:4c5290f42ca4b627ecb6f5f080cf06a651a5478d47653dbd634e004ff850066b"},{"exercise_id":"zh-a1-u12-listen-e10","item_id":"zh.gen.listen_choice.zh-xie","options_hash":"v1:c7274471a559ffaa9d4ceff3bb666791ecb235273fb53643d3d850cd50f4b934"},{"exercise_id":"zh-a1-u12-words-e01","item_id":"zh.gen.translation_choice.zh-yigong","options_hash":"v1:a4e6488810333969e5ab820f45767581d2b2ee290c6e5516693a5274a624633f"},{"exercise_id":"zh-a1-u12-words-e05","item_id":"zh.gen.translation_choice.zh-tai","options_hash":"v1:2f4a808aa3bf3035bf5aa7a53d5a71eb55ff18575dd72d94486cab32d7d57045"},{"exercise_id":"zh-a1-u12-words-e06","item_id":"zh.gen.translation_choice.zh-ne","options_hash":"v1:2dfec47b89b3828e161da31be262a09a3a743ca71957b693a7be55bad1f184bc"},{"exercise_id":"zh-a1-u12-words-e08","item_id":"zh.gen.translation_choice.zh-xie","options_hash":"v1:90998eab2f9cb40f66e4e6ece82361c257cbb2cf02a11eae79595d02ff4c5c24"},{"exercise_id":"zh-a1-u12-words-e10","item_id":"zh.gen.translation_choice.zh-tai-hao-le","options_hash":"v1:928c40d89dda467b7e958b9d0557a72af93638d83f9c0b9865f790c724f2ee89"},{"exercise_id":"zh-a1-u12-final-e03","item_id":"zh-a1-u12-l02-e05","options_hash":"v1:80eebe0701ae09eeb877711e99a19a9985c449ec465ba70483be48f9f56c30ad"},{"exercise_id":"zh-a1-u12-final-e04","item_id":"zh.gen.listen_choice.zh-duoshao","options_hash":"v1:edb33993d88f4d50bbacc2c575e20cfdaca86752ca3ce5c05816b5eda5ea0ff4"},{"exercise_id":"zh-a1-u12-final-e05","item_id":"zh.gen.translation_choice.zh-mai-comprar","options_hash":"v1:2cbc64268ae95800ce828f151e1933afcfacc42ad301b49ae9edfb0ce9bb14aa"}]}}$content$::jsonb;
begin

-- Conjuntos de opciones (content/option-sets.ts).
declare
  v_bad text;
begin

select string_agg(item_id || '@' || options_hash, ', ') into v_bad from (
  select x.item_id, x.options_hash
  from jsonb_to_recordset(d -> 'catalog' -> 'option_sets')
    as x(item_id text, version_hash text, options_hash text)
  left join public.exercise_item_versions v on v.item_id = x.item_id and v.content_hash = x.version_hash
  where v.id is null
  order by 1, 2 limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_option_sets: conjuntos de una versión que no existe: %', v_bad;
end if;

select string_agg(item_id || '@' || options_hash, ', ') into v_bad from (
  select x.item_id, x.options_hash
  from jsonb_to_recordset(d -> 'catalog' -> 'option_sets')
    as x(item_id text, version_hash text, options_hash text, format text, options jsonb, answer_index smallint)
  join public.exercise_item_versions v on v.item_id = x.item_id and v.content_hash = x.version_hash
  join public.exercise_option_sets s on s.item_version_id = v.id and s.options_hash = x.options_hash
  where (s.format, s.options, s.answer_index) is distinct from (x.format, x.options, x.answer_index)
  order by 1, 2 limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_option_sets: conjuntos ya cargados con el mismo hash y otras opciones: %', v_bad;
end if;

insert into public.exercise_option_sets (item_id, item_version_id, options_hash, format, options, answer_index,
  origin, generator, generator_version)
select x.item_id, v.id, x.options_hash, x.format, x.options, x.answer_index, x.origin, x.generator,
  x.generator_version
from jsonb_array_elements(d -> 'catalog' -> 'option_sets') with ordinality as t(j, ord),
  jsonb_to_record(t.j)
    as x(item_id text, version_hash text, options_hash text, format text, options jsonb, answer_index smallint,
         origin text, generator text, generator_version text)
join public.exercise_item_versions v on v.item_id = x.item_id and v.content_hash = x.version_hash
where not exists (select 1 from public.exercise_option_sets s
                  where s.item_version_id = v.id and s.options_hash = x.options_hash)
order by t.ord;

end;

-- Conjunto vigente de cada ubicación de elección (content/option-sets.ts).
declare
  v_bad text;
begin

select string_agg(exercise_id, ', ') into v_bad from (
  select x.exercise_id
  from jsonb_to_recordset(d -> 'catalog' -> 'placement_option_sets')
    as x(exercise_id text, item_id text, options_hash text)
  left join public.exercises e on e.id = x.exercise_id
  left join public.exercise_option_sets s
    on s.item_version_id = e.item_version_id and s.options_hash = x.options_hash
  where e.id is null or e.item_id is distinct from x.item_id or s.id is null
  order by 1 limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_option_sets: ubicaciones sin fila, de otro ítem o sin ese conjunto en su versión: %', v_bad;
end if;

update public.exercises e set option_set_id = s.id
from jsonb_to_recordset(d -> 'catalog' -> 'placement_option_sets')
  as x(exercise_id text, item_id text, options_hash text)
join public.exercise_option_sets s on s.options_hash = x.options_hash
where e.id = x.exercise_id and s.item_version_id = e.item_version_id
  and e.option_set_id is distinct from s.id;

-- Checksum de la duplicación transitoria: exercises conserva la copia que lee la app.
select string_agg(id, ', ') into v_bad from (
  select e.id
  from public.exercises e
  join public.exercise_option_sets s on s.id = e.option_set_id
  where e.id in (select x ->> 'exercise_id' from jsonb_array_elements(d -> 'catalog' -> 'placement_option_sets') x)
    and ((select jsonb_agg(o -> 'text' order by n) from jsonb_array_elements(s.options) with ordinality as t(o, n))
           is distinct from e.payload -> 'options'
         or s.options -> s.answer_index::integer ->> 'text' is distinct from e.answer)
  order by e.id limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_option_sets: la copia de exercises no coincide con su conjunto: %', v_bad;
end if;

select string_agg(id, ', ') into v_bad from (
  select e.id
  from jsonb_to_recordset(d -> 'catalog' -> 'placement_versions') as x(exercise_id text)
  join public.exercises e on e.id = x.exercise_id
  where e.type in ('image_choice', 'translation_choice', 'fill_blank', 'listen_choice')
    and e.option_set_id is null
  order by e.id limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_option_sets: ubicaciones de elección con versión y sin conjunto: %', v_bad;
end if;

end;

end
$polygo_content$;
